// ReviewQueueAll iterates every item of ReviewQueue, following the cursor page by page; it stops at
// the first error.
func (c *Client) ReviewQueueAll(ctx context.Context, params *traust.ReviewQueueParams) iter.Seq2[traust.ReviewCase, error] {
	var page traust.ReviewQueueParams
	if params != nil {
		page = *params
	}
	return traust.Pages(func(cursor *string) ([]traust.ReviewCase, *string, error) {
		page.Cursor = cursor
		found, err := c.ReviewQueue(ctx, &page)
		if err != nil {
			return nil, nil, err
		}
		return found.Items, found.Next, nil
	}, page.Cursor)
}

